#!/usr/bin/env bash
set -euo pipefail

echo "Aplicando Token Monitor Jean — Beta 0.2..."

mkdir -p "$(dirname "app/src/main/java/com/jean/tokenmonitor/MainActivity.java")"
echo "" | base64 -d > "app/src/main/java/com/jean/tokenmonitor/MainActivity.java"

mkdir -p "$(dirname "app/src/main/java/com/jean/tokenmonitor/WalletGateway.java")"
echo "" | base64 -d > "app/src/main/java/com/jean/tokenmonitor/WalletGateway.java"

mkdir -p "$(dirname "app/src/main/java/com/jean/tokenmonitor/DisabledWalletGateway.java")"
echo "" | base64 -d > "app/src/main/java/com/jean/tokenmonitor/DisabledWalletGateway.java"

mkdir -p "$(dirname "app/build.gradle")"
echo "" | base64 -d > "app/build.gradle"

mkdir -p "$(dirname "app/src/main/AndroidManifest.xml")"
echo "" | base64 -d > "app/src/main/AndroidManifest.xml"

mkdir -p "$(dirname ".github/workflows/build-apk.yml")"
echo "" | base64 -d > ".github/workflows/build-apk.yml"

mkdir -p "$(dirname "README.md")"
echo "" | base64 -d > "README.md"

git config user.name "Token Monitor Setup"
git config user.email "tokenmonitor@users.noreply.github.com"
git add app .github README.md
git commit -m "Token Monitor Beta 0.2" || true
git push origin HEAD

echo "Beta 0.2 enviada. O GitHub Actions vai gerar o novo APK automaticamente."
